    59      bool Photoshop::valid(const byte* pPsData, size_t sizePsData)
    60      {
    61          const byte* record = nullptr;
    62          uint32_t sizeIptc = 0;
    63          uint32_t sizeHdr = 0;
    64          const byte* pCur = pPsData;
    65          const byte* pEnd = pPsData + sizePsData;
    66          int ret = 0;
    67          while (pCur < pEnd
    68                 && 0 == (ret = Photoshop::locateIptcIrb(pCur, (pEnd - pCur), &record, &sizeHdr, &sizeIptc))) {
    69              pCur = record + sizeHdr + sizeIptc + (sizeIptc & 1);
    70          }
    71          return ret >= 0;
    72      }
